// viewport
vec2 pix2viewport(in vec2 uv)
{
    return 1.1 * (2.*uv-iResolution.xy)/iResolution.y;
}

// viewport parameters
const float vi_dist = 8.;

// manifold parameters
struct t_mf
{
    float bb_size;    // bounding box size

    float rm_imax;    // iterations maximum
    float rm_fh;      // factor step length 

    float b0_sh_a0;   // shift amplitude 0
    float b0_T_w;     // free
};

t_mf mf;

// manifold
const float PS_f   = 4.;
const float PS_e_f = 3.;
vec2 tex_subdiv = vec2(2.) * vec2(PS_e_f, PS_e_f);
vec3 rg_bounds = vec3(1.,1.,1.);

void buf_mf_read( inout t_mf mf )
{
    mf.bb_size     = 4.;

    mf.rm_imax     = 600.;
    mf.rm_fh       = 0.033;

    mf.b0_sh_a0    = -1.;
    mf.b0_T_w      = 1.1;
}

struct t_hit
{
    vec2  tR;
    float t;
    int   i;
    vec3  p ;
    vec3  n ;

    vec4  rg_mat;
    vec4  ta_mat;
    vec4  tt_mat;
    vec4  tg_mat;
};

t_hit hit;

float map( in vec3 p)
{
    float res = hit.tR.y;

    // world cartesian base
    const vec3 ex = normalize(vec3(+1., +0., +0.));

    // rhombohedron normal surface vectors
    const vec3 rh_ex = normalize(vec3(+1., -1., +1.));
    const vec3 rh_ey = normalize(vec3(+1., +1., -1.));
    const vec3 rh_ez = normalize(vec3(-1., +1., +1.));
    const vec3 rh_ew = -normalize(rh_ex + rh_ey + rh_ez);

    float l0_x_gs = mf.b0_T_w;
    p /= l0_x_gs;
    {
        /// rhombic_grid
        // cartesian to rohmbohedron coords(1)
        const mat3 M_c2r = mat3(rh_ex, rh_ey, rh_ez);        
        vec3 l0_x = M_c2r * p;

        // shift, center grid(2) 
        l0_x += vec3(0.5);   

        // rhomboeder_cell index  
        vec3 l0_x_id = clamp(floor(l0_x), -rg_bounds, +rg_bounds);

        // local coords, map n rhomboeder_cells to one cell
        l0_x -= l0_x_id;

        // shift, center cell(2)
        l0_x -= vec3(0.5);

        // rhombohedron 2 cartesian coords(1)
        p  = inverse(M_c2r) * l0_x;

        hit.rg_mat.xyz = l0_x_id; // rhombohedron cell id
    }
    {
        // axis tetraeders inside rhomboeder shift axis
        const float co = dot(ex, rh_ew);
        const vec3 er = cross(ex, rh_ew);
        const float si = length(er);
        const vec3 ern = normalize(er); 

        mat3 m_c2t = rota(ern, co, -si);
        mat3 m_t2c = rota(ern, co, +si); 

        // rotation from tetrahedron ew axis to cartesian ex axis
        p = m_c2t * p;

        // mirror, translate, invert
        float x0 = 0.3735;
        float sign_px = sign(p.x);
        p.x = -(abs(p.x) - x0);
        if (sign_px > 0.) p.zy *= -1.;

        // scale
        p *= sqrt(3.);

        // back rotation from cartesian ex axis to tetrahedron ew axis
        p = m_t2c * p;

        hit.ta_mat.x = sign_px; // signum mirrored axis
    }
    p *= l0_x_gs;

    vec2 z = vec2(0.);
    {
        //// sdf's
        vec2 z = vec2(0.);

        //sig(sr): sens of rotation, abs(sr) : number edges per face
        float cell_id = 0., sr = 0.;
        p = tetrahedralsphere(p, mf.b0_sh_a0, cell_id, sr);       

        float rxy = 0., au = 0.0, av = 0.0;
        float fracu = 1.0;
        ////fractal level 0:
        au = atan(p.y, p.x);
        rxy = length(p.xy); 
        z = vec2(rxy, p.z);
        z = cmul(z,z); z.x -= mf.b0_sh_a0;

        ////fractal level 1:
        z = cpow( z, 2.);

        p = vec3(log(length(z)), 0.5*au/PI, 0.5*atan(z.y,z.x)/PI); // r,u,v
        hit.tt_mat.x  = cell_id;
        hit.tt_mat.yz = z;
        hit.tt_mat.w  = au *fracu;
        res = p.x;
    }
    {
        /// truchet 3d
        float TC3D_nu = tex_subdiv.x;
        float TC3D_nv = tex_subdiv.y;
        const float TC3D_nr = 1.;

        p *= vec3(TC3D_nr,TC3D_nu,TC3D_nv); // r,u,v
        p.yzx = p.xyz;

        ivec3 l0 = -ivec3(TC3D_nv/2.,0      ,TC3D_nu/2.);
        ivec3 l1 = +ivec3(TC3D_nv/2.,TC3D_nr,TC3D_nu/2.)-ivec3(1.);
        vec3 tc_id = floor(p);
        tc_id = clamp(tc_id, vec3(l0), vec3(l1));
        vec3 q = p - tc_id -0.5;

        // random
        float rnd = hash21(tc_id.xz);

        // flip cell direction randomly
        if(rnd<.5) q.x = -q.x;

        // sdf
        float r0 = 0.5; float r1 = 0.125;
        float d;
        if(fract(rnd*77.57+iTime/6.)>.75) {
           // offset-xz circle, id diagonal sub domain
           vec3 q2 =  length(q.xz-.5)<length(q.xz+.5)
                ? vec3(q.xz-.5,0.)  
                : vec3(q.xz+.5,1.);
           d = sdTorus( vec3(q2.x, q.y, q2.y) ,vec2(0.5,r1) );
        }
        else {
           d = opSmoothUnion( sdCylinder( q.zxy, r1 ), sdCylinder( q.xzy, r1 ), 0.05 );
        }
        // cell alpha
        float tc_a = sdBox( q, vec3(r0*0.9)); float px = fwidth(tc_a);
        tc_a = smoothstep(px,-px,tc_a);

        /// return
        hit.tg_mat.xy = z;
        hit.tg_mat.z  = tc_a;
        hit.tg_mat.w  = rnd; 
        res = d;
    }
    return res;
}

vec3 calcNormal( in vec3 pos, in float px )
{
	vec2 e = vec2(1.0,-1.0)*0.5773*0.25*px;
	return normalize( e.xyy*map( pos + e.xyy) +
					  e.yyx*map( pos + e.yyx) +
					  e.yxy*map( pos + e.yxy) +
					  e.xxx*map( pos + e.xxx) );
}

void intersect( in vec3 ro, in vec3 rd, in float px)
{   
    // bb came
    float rm_rlmin = 0.0;
    float rm_rlmax = length( vec3(abs(mf.bb_size)) ) + abs(vi_dist) + 0.1;

    hit.tR = vec2( max(rm_rlmin,0.0), rm_rlmax);
    hit.n  = -rd; 

	// bb cube
	vec2 bb_tR; vec3 bb_n;      
    bb_tR = bbbox( ro, rd, vec3(abs(mf.bb_size)), bb_n);

    // intersection: update bb shape, ray length range, normal
    if (bb_tR.x > hit.tR.x ) {hit.tR.x = bb_tR.x; hit.n =
    bb_n;} // near boundary                       
    if (bb_tR.y < hit.tR.y ) {hit.tR.y = bb_tR.y;} // far boundary
    // init with no rayintersection
    hit.t = -1.0;

    // bb shape befor camera
	if( hit.tR.y>=0.0 )
    {
        //SDF
        float fh = mf.rm_fh;
        float t = hit.tR.x;          // ray marching start
        int i_count = 0;
        for( int i=i_count; i<int(mf.rm_imax); i++  )
        {
            vec3 pos = ro + rd*t;
            float th = px*t;         // sdf bound surface hit
            float h = map(pos);
            if( t>hit.tR.y || h<th ) break; // ray is outside bb shape OR sdf_surface_hit.
            t += h*fh;                      // accumulate step lengths
            i_count = i;
        }

        // ray on or inside bb shape
        if( hit.tR.x<=t && t<hit.tR.y )
        {
            hit.t = t;
            hit.i = i_count;
            hit.p = ro + rd * t;
            hit.n = (t == hit.tR.x) ? hit.n : calcNormal( hit.p, px );
        }
    }
}

// came
vec3 came_rot(in vec3 p, in float time) {
	// camera transformation
	if (iMouse.x > 0.0)
	{
        vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;
		p.yz = crot(p.yz,PI*m.y);
		p.zx = crot(p.zx,-PI*m.x);
	}
	p.xz = crot(p.xz,0.1 * time);
	return p.xyz;
}

void mainImage( out vec4 O, in vec2 uv )
{
    /// data
    buf_mf_read(mf);

    float rg_mode = floor(4.*fract(iTime/40.));
    rg_bounds = (rg_mode < 2.) 
        ? ((rg_mode < 1.) ? vec3(1.,1.,1.)
                          : vec3(1.,1.,0.))
        : ((rg_mode < 3.) ? vec3(1.,0.,0.)
                          : vec3(0.,0.,0.));

    /// viewport
    vec2 U = pix2viewport(uv);

	/// camera   
	float fle = 2.0;
    vec3  ro = came_rot(vec3(0,0,vi_dist),iTime);
    vec3  rd = normalize(came_rot(vec3(U.x,U.y,-fle),iTime));

	/// ray march
    float px = 2.0/( iResolution.y*fle );  
	intersect(ro, rd, px);
    vec3 p = hit.p, n = hit.n;

	/// lighting
    // sun
    vec3  sun_li_dir        = normalize(vec3(+0.5,-1,0.));
    vec3  sun_li_amp_col    = vec3(0.949,0.831,0.871);
    vec3  sun_li_diff_col   = vec3(1.);
    vec3  sun_li_spec_col   = vec3(1.000,1.000,0.800);
    float sun_li_spec_shi   = 3.;

	/// color    
	vec3 col = vec3(0.);
    vec3 bg_col = vec3(0);
    // color background
	if (hit.t < 0.0)
    {
        // vignette
        col = vec3(0.3);
        float grain = (1.-pow( mix(hash(uv), length( U/2.), .8), 1.5));
        col *=  mix(vec3(grain), col, .5);
        bg_col = col;    
	}
    // color surface sdf or bb shape
    else
    {       
        /// texture surface
        vec3 a3 = alpha3( iTime/10. );
        // SHOW_GRID_CYCLE
        vec3 col_gc = vec3(0.);
        if ( a3.x != 0.)
        {
            col_gc = vec3(0.5*(hit.ta_mat.x + 1.));
        }
        // SHOW_TETRA_DOMAINS
        vec3 col_td = vec3(0.);
        if ( a3.y != 0. )
        {
            col_td = h2rgb(hit.tt_mat.x/PS_f);
        }
        // SHOW_GRID_TRUCHET
        vec3 col_gt = vec3(0.);
        if ( a3.z != 0. )
        {
            vec4 C = truchet3D(hit.tg_mat.w, hit.tg_mat.z, iTime/60.); C.rgb *= 0.5;
            col_gt = C.xyz;
        }
        // mix3
        col = col_gc * a3.x + col_td * a3.y + col_gt * a3.z;
        col = clamp(col, 0., 1.);

        /// shade
        // sun light
        col = phong_light(rd, n, col
                         ,sun_li_dir
                         , 0.2 * sun_li_amp_col
                         , 0.5 * sun_li_diff_col
                         , 0.3 * sun_li_spec_col
                         , sun_li_spec_shi);
    }
    col = clamp(col, 0., 1.);
    O = vec4(col,1.);

    /// gamma correction
    O = vec4(rgb2srgb(O.rgb),1.);
}

/// constants
const float PI_2 = acos(0.), PI = 2.*PI_2, PI2 = 2.*PI;

/// 1D transformations
float hash(vec2 p)
{
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float hash21(vec2 p)
{
    return fract(sin(dot(p, vec2(27.609, 57.583)))*43758.5453);
}

/// 2D transformations
/// complex
vec2 cmul(vec2 za,vec2 zb)
{
    return za*mat2(zb.x,-zb.y,zb.yx);
}

vec2 crot(vec2 z,float a)
{
    return cmul(vec2(cos(a),sin(a)),z);
}

vec2 cinv(vec2 z)
{
    return z*vec2(1,-1)/dot(z,z);
}

vec2 cdiv(vec2 z, vec2 w)
{
    return cmul(z,cinv(w));
}

vec2 cpow(vec2 z, float q)
{
    float r=pow(length(z), q);
	float a=q*atan(z.y,z.x);
    return vec2(r*cos(a),r*sin(a));
}

vec2 cTeraPolyArc2disk(vec2 z)
{
    // https://people.maths.ox.ac.uk/trefethen/lightning.html
    const int NUM_j = 15; // poles
    const vec2[NUM_j] rf = vec2[]
    (vec2(-0.4534, -0.8913)
    ,vec2( 0.5001,  0.8660)
    ,vec2(-1.0000,  0.0001)
    ,vec2( 0.5008, -0.8656)
    ,vec2(-0.5452,  0.8383)
    ,vec2( 0.1901,  0.9818)
    ,vec2( 0.9875, -0.1576)
    ,vec2(-0.9856, -0.1691)
    ,vec2( 0.4224, -0.9064)
    ,vec2( 0.5738,  0.8190)
    ,vec2(-0.9995,  0.0311)
    ,vec2( 0.4858,  0.8741)
    ,vec2( 0.5760, -0.8175)
    ,vec2(-1.0000, -0.0061)
    ,vec2( 0.4959, -0.8684));

    const vec2[NUM_j] rw = vec2[]
    (vec2( 0.2728,  0.0   )  
    ,vec2( 0.0003,  0.0126)
    ,vec2(-0.0016, -0.0121)
    ,vec2(-0.0172,  0.0324)
    ,vec2( 0.1417, -0.4629)
    ,vec2(-0.4681, -0.2288)
    ,vec2(-0.2433,  0.2822)
    ,vec2( 0.1996, -0.0082)
    ,vec2( 0.2884, -0.0353)
    ,vec2(-0.0666,  0.1824)
    ,vec2(-0.0357, -0.1136)
    ,vec2(-0.1091,  0.0396)
    ,vec2(-0.0831,  0.2627)
    ,vec2( 0.0598, -0.0284)
    ,vec2( 0.0597,  0.0760));

    const vec2[NUM_j] rz = vec2[]
    (vec2(-0.239570, -0.459171)
    ,vec2( 0.354172,  0.611300)
    ,vec2(-0.706487,  0.001072)
    ,vec2( 0.356785, -0.606740)
    ,vec2(-0.277869,  0.437059)
    ,vec2( 0.047259,  0.573454)
    ,vec2( 0.515842, -0.066306)
    ,vec2(-0.591622, -0.166501)
    ,vec2( 0.221135, -0.605193)
    ,vec2( 0.413545,  0.494105)
    ,vec2(-0.671697,  0.057599)
    ,vec2( 0.309337,  0.611574)
    ,vec2( 0.414577, -0.491758)
    ,vec2(-0.695342, -0.019940)
    ,vec2( 0.334074, -0.612218));

    // polynomial barycentric representation
    vec2 zn = vec2(0.); vec2 zd = vec2(0.);       
    for(int j = 0; j<NUM_j; j++)
    {
        vec2 zj = cdiv( rw[j], (z-rz[j]));
        zd += zj; // sum denominator
        zn += cmul(rf[j], zj); // sum nominator
    }
    return cdiv(zn, zd);;
}

/// stereographic projection 
float sig(float x)
{
    return x < 0. ? -1. : +1.; 
}

float dist(float x, float e)
{
    // e in [0., +inf]
    return sign(x)*abs( pow(sign(x)*x, abs(e)) );
    //return sign(x)*abs( pow(abs(x), abs(e)) );
}

vec2 r_poly_dist(vec2 z, vec2 e, float sh_a)
{   
    /// r-polygon-distribution
    float r = length(z); z = (r<0.)? vec2(0) : z/r; 
    float d0 = 0.5 *abs(e.y-e.x);
    float e2 = e.x + d0 + d0 * (2.*smoothstep(-1., 1., -sh_a) - 1.);
    return dist(r, e2) * z;
}   

vec3 sp(vec3 zsr)
{
    vec2 z = zsr.xy; float sr = zsr.z;
    // stereopraphic projection (complex plane to unit sphere)
    float zz = dot(z,z); vec3 pn;
    if (bool(sig(sr))) {// north pole
        pn = vec3(2. * z.x,  2. * z.y, -1. + zz);
        }
    else { // south pol
        z = cinv(z);
        pn = vec3(2. * z.x, -2. * z.y,  1. - zz);
        }
    pn /= 1.+zz;
    return pn;
}

vec3 spb(vec3 zsr)
{
    vec2 z = zsr.xy; float sr = zsr.z;
    // inverse stereograpic projection
    float k = 2./(1.+dot(z,z)); vec3 pn;
    if (bool(sig(sr))) {// north pole
        pn = vec3(k*z, k-1.); }
    else { // south pol
        z = cinv(z);
        pn = vec3(k*z, -(k-1.)); }
    return pn;
}

/// 3D transformations
mat3 rota(in vec3 axis, in float c, in float s)
{
    //axis : unit vector rotation axis; c : cos(a), s : sin(a);
    return mat3 (          c,  axis.z * s, -axis.y * s,
                 -axis.z * s,           c,  axis.x * s,
                  axis.y * s, -axis.x * s,           c) + (1.0 - c) * outerProduct(axis, axis);
}

vec3 tetra_cells(in vec3 p, out float cell_id, out float sr)
{
// map spherical platonic solid pyramidal-face-cells to one cell located at -z-axis.
	// tetrahedron (bounded by a cube)
	// cells: A,B,C,D
	// cell walls defined by the face_normal
    bool nBA = dot(vec3( 1., 0.,-1.),p)>=0.;
	bool nCA = dot(vec3( 0., 1.,-1.),p)>=0.;
	bool nDA = dot(vec3( 1., 1., 0.),p)>=0.;
	bool nCB = dot(vec3(-1., 1., 0.),p)>=0.;
	bool nDB = dot(vec3( 0., 1., 1.),p)>=0.;
	bool nDC = dot(vec3( 1., 0., 1.),p)>=0.;

    // map n-cells to 1-cell by rotation
    // rotation angles
    const float a45 = PI/4.;             // 45° 
    const float a35 = atan(sqrt(8.))/2.; // 35.264°
    const float a30 = PI/6.;             // 30°

    const vec2 ei_a45 = vec2(cos(a45), sin(a45));
    const vec2 ei_a35 = vec2(cos(a35), sin(a35));
    const vec2 ei_a30 = vec2(cos(a30), sin(a30));

    vec2 ei_y = ei_a45;   
    vec2 ei_x = ei_a35;
    vec2 ei_z = ei_a30;
    // symmetries
    if(nBA && nCA && nDA) //inside cell A
	{
		cell_id =  0.;
        ei_x.y *= -1.; // a = -35.264°
	}
	else if( nCB && nDB && !nBA) //inside cell B
	{
		cell_id =  1.;
		ei_y   *= -1.; // a = -3.*45°
        ei_x.y *= -1.; // a = -35.264°
	}
	else if(!nCA && !nCB && nDC) //inside cell C
	{
		cell_id =  2.;
		ei_y.x *= -1.; // a = +3.*45°
		ei_z.y *= -1.; // a = -30°
	}
	else if(!nDA && !nDB && !nDC)//inside cell D
	{
		cell_id =  3.;
		ei_y.y *= -1.; // a = -45°
		ei_z.y *= -1.; // a = -30°
	}
	p.zx = cmul(p.zx,ei_y); // y-axis
	p.yz = cmul(p.yz,ei_x); // x-axis
	p.xy = cmul(p.xy,ei_z); // z-axis
	// 3 edges per face, non cyclic
	sr = 3.;
    return p;
}

vec3 tetrahedralsphere(in vec3 p, in float PS_a0, out float cell_id, out float sr)
{   
    cell_id = 0.;
    sr = 0.;

    //// map platonic solid cells to one cell
    vec3 pn = normalize(p);  

    // projection from n cells to 1 cell. 

    pn = tetra_cells(pn, cell_id, sr);    

    // invers stereographic projection
    vec2 z = pn.xy/(1.-pn.z);
    z = cTeraPolyArc2disk(z);

    /// r-polygon-distribution
    vec2 e = vec2(sqrt(2.), 0.5);
    float en = 1.+( (PS_a0<0.?e.x:e.y)-1. )*smoothstep(1.,5., abs(PS_a0));
    float r = length(z); vec2 zn = z/r;
    en = 1.;
    z = dist(r, en) * zn;

    /// stereograpic projection    
    pn = sp(vec3(z,sr));

    /// scale radius
    return length(p) * pn;
}

/// raymarch
// sdf operators
// union
float opSmoothUnion( in float d1, in float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

// intersection
float opI( in float d1, in float d2 )
{
    return max(d1,d2);
}

// round
float opR( in float sdf, in float r )
{
    return sdf - r;
}

// sdf 3d primitives
float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdCylinder( vec3 p, float r )
{
  return length(p.xz)-r;
}

float sdTorus( vec3 p, vec2 t )
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

/// bounding shapes

vec2 bbbox( in vec3 ro, in vec3 rd, in vec3 boxSize, out vec3 norm )
{
	// axis aligned box centered at the origin, with size boxSize
	vec3 m = 1.0/rd;
	vec3 n = m*ro;
	vec3 k = abs(m)*boxSize;
	vec3 t1 = -n - k;
	vec3 t2 = -n + k;
	float tN = max( max( t1.x, t1.y ), t1.z );
	float tF = min( min( t2.x, t2.y ), t2.z );
	if( tN>tF || tF<0.0) return vec2(-1.); // no intersection
	norm = -sign(rd)*step(t1.yzx,t1.xyz)*step(t1.zxy,t1.xyz); // normal
	return vec2( tN, tF );
}

// colorspace transformations
vec3 h2rgb( in float h )
{
    vec3 rgb = clamp( abs(mod(h*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
    return rgb*rgb*(3.0-2.0*rgb); /* cubic smoothing */
}

vec4 truchet3D(in float rnd, in float a ,in float time)
{
    return mix(vec4(1.), vec4(h2rgb( fract(abs(rnd)*22.93 + time)),1.), a);
}

vec3 alpha3( in float x )
{
    vec3 a = mod( x * 6. -vec3(0.,2.,4.)-vec3(0.5) ,6.);
    a = abs(a - 3.) - 1.5;
    a = clamp(a, 0., 1.);
    a = a*a*(3.0-2.0*a);
    return a;
}

// shade
vec3 phong_light(vec3 ray_dir,
                 vec3 hit_norm,             
                 vec3 mat_col,
                 vec3 li_dir,
                 vec3 li_amb_col,
                 vec3 li_diff_col,
                 vec3 li_spec_col, float li_spec_shininess)          
{
    // make shure we are working with normalized orientation vectors
    ray_dir  = normalize(ray_dir); // from came  to surface
    li_dir   = normalize(li_dir);  // from light to surface
    hit_norm = normalize(hit_norm);

    // amb_col : ambient reflected light
    float cosa = 1.;
    vec3 amb_col  = mat_col * li_amb_col * cosa;

    // diff_col: diffuse reflected light
    cosa = clamp(dot(-li_dir, hit_norm), 0., 1.);
    vec3 diff_col = mat_col * li_diff_col * cosa;

    // spec_col: specular reflected light 
    vec3 li_dir_ref = reflect(li_dir, hit_norm);
    cosa = pow(clamp(dot(li_dir_ref, -ray_dir), 0., 1.), li_spec_shininess);
    vec3 spec_col = vec3(0.);
    if (cosa > 0.) {
      //diff_col = diff_col * (1.0 - cosa);
      spec_col = li_spec_col * cosa;    
    }

    // add all the reflected light types at the ray surface intersection point.
    vec3 col = vec3(0.);
    col+= amb_col;
    col+= diff_col; 
    col+= spec_col;
    return col;    
}

// srgb <--> rgb (linear)
vec3 srgb2rgb(in vec3 col)
{
    return pow(col, vec3(2.2));
}

vec3 rgb2srgb(in vec3 col)
{
    return pow(col, vec3(1./2.2));
}
